def glom_cli(target, spec, indent, debug, inspect, scalar):
    from glom import glom as glom_func
    from glom import GlomError

    try:
        val = glom_func(target, spec)
    except GlomError as e:
        if debug:
            import pdb; pdb.post_mortem()
        raise CommandLineError(str(e))

    if inspect:
        Inspect(val).interact()
        return

    if scalar and is_scalar(val):
        print(val)
    else:
        if indent == 0:
            print(json.dumps(val, separators=(',', ':')))
        else:
            print(json.dumps(val, indent=indent))


