    from glom.cli import glom_cli, mw_get_target, mw_handle_target

    cmd = Command(
        glom_cli,
        [
            Flag('--target-file', help='path to target data source (optional)'),
            Flag('--target-format', default='json',
                help='format of the source data (json, python, toml, or yaml) '
                     '(defaults to \'json\')'),
            Flag('--spec-file', help='path to glom spec definition (optional)'),
            Flag('--spec-format', default='python',
                help='format of the glom spec definition (json, python, '
                     'python-full) (defaults to \'python\')'),
            Flag('--indent', type=int, default=2,
                help='number of spaces to indent the result, 0 to disable '
                     'pretty-printing (defaults to 2)'),
            Flag('--debug', action='store_true',
                help='interactively debug any errors that come up'),
            Flag('--inspect', action='store_true',
                help='interactively explore the data'),
            Flag('--scalar', action='store_true',
                help='print scalar values without quotes'),
        ],
        pos_args=[
            PosArgSpec('spec', display=PosArgDisplay.OPTIONAL),
            PosArgSpec('target', display=PosArgDisplay.OPTIONAL),
        ],
        middleware=[mw_get_target, mw_handle_target],
    )

    return cmd


def mw_handle_target(target_text, target_format):
    if target_text is None:
        return {'target': None}

    if target_format == 'json':
        try:
            target = json.loads(target_text)
        except ValueError as e:
            raise CommandLineError('could not load target data: %s' % e)
    elif target_format == 'python':
        try:
            target = ast.literal_eval(target_text)
        except (ValueError, SyntaxError) as e:
            raise CommandLineError('could not load target data: %s' % e)
