            import yaml
            target = yaml.safe_load(target_text)
        except Exception as e:
            raise CommandLineError('could not load target data: %s' % e)
    elif target_format == 'toml':
        try:
            import toml
            target = toml.loads(target_text)
        except Exception as e:
            raise CommandLineError('could not load target data: %s' % e)
    else:
        raise CommandLineError('target-format to be one of: json, python, yaml, toml')

    return {'target': target}


